public static int calculateTimeNeeded(int N) {
    // handle edge cases
    if (N <= 1) {
        return 0;
    }
    if (N <= 3) {
        return 1;
    }

    // calculate the number of swaps needed
    int swaps = N / 2 + (N % 2 == 1 ? 0 : 1);
    // calculate the time needed in minutes
    int time = (swaps * N * (swaps - 1)) / 2;
    return time;
}

