public static String convertDatesToWeekdays(String date) {
    // Check if the input date is in the correct format
    if (!date.matches("\\d{2} \\d{2} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Parse the date into a LocalDate object
    LocalDate localDate = LocalDate.parse(date, DateTimeFormatter.ofPattern("MM dd yyyy"));

    // Convert the LocalDate to a WeekDay object
    WeekDay weekDay = WeekDay.of(localDate);

    // Return the weekday of the date in the requested format
    return weekDay.name + " " + localDate.toString();
}

